// Normalize any actor's output into one lead shape, attach settings, dedupe, cap.
const settings = $('Your settings (EDIT ME)').first().json;
const max = Number(settings.maxLeadsPerRun) || 25;
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  if (j.error) continue;
  const lead = {
    leadType: j.leadType ?? j.type ?? 'lead',
    state: j.state ?? j.region ?? '',
    businessName: j.businessName ?? j.name ?? j.title ?? j.company ?? '',
    ownerName: j.ownerName ?? j.owner ?? j.contactName ?? '',
    address: j.address ?? j.street ?? '',
    city: j.city ?? '',
    county: j.county ?? '',
    zip: j.zip ?? j.postalCode ?? '',
    eventDate: j.eventDate ?? j.date ?? '',
    sourceUrl: j.sourceUrl ?? j.url ?? '',
  };
  const key = [lead.businessName, lead.ownerName, lead.address].join('|').toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  lead.leadText = JSON.stringify({ ...lead, extra: undefined, licenseType: j.licenseTypeDescription ?? j.licenseType ?? undefined, status: j.status ?? undefined });
  lead.icpDescription = settings.icpDescription;
  lead.offerDescription = settings.offerDescription;
  lead.scoreThreshold = Number(settings.scoreThreshold) || 7;
  out.push({ json: lead });
  if (out.length >= max) break;
}
if (out.length === 0) {
  return [{ json: { _empty: true, note: 'No new leads this run.' } }];
}
return out;

