// Parse the model's JSON verdict and produce the final row shape.
const rows = [];
for (const item of $input.all()) {
  const j = item.json;
  let verdict = { score: 0, reason: 'AI call failed' };
  try {
    const content = j.choices?.[0]?.message?.content;
    if (content) verdict = JSON.parse(content);
  } catch (e) { verdict.reason = 'AI returned unparseable output'; }
  rows.push({ json: {
    processedAt: new Date().toISOString(),
    leadType: j.leadType ?? '',
    state: j.state ?? '',
    businessName: j.businessName ?? '',
    ownerName: j.ownerName ?? '',
    address: j.address ?? '',
    city: j.city ?? '',
    county: j.county ?? '',
    zip: j.zip ?? '',
    eventDate: j.eventDate ?? '',
    sourceUrl: j.sourceUrl ?? '',
    score: Number(verdict.score) || 0,
    reason: String(verdict.reason ?? ''),
    scoreThreshold: j.scoreThreshold ?? 7,
  }});
}
return rows;
